// Extrai a mensagem de texto do payload da WhatsApp Cloud API.
// Ignora eventos de status (entregue/lido) e mensagens que não são texto.
const out = [];
// Normaliza números do Brasil: a Meta pode enviar sem o 9º dígito (ex.: 556400000000).
// Adiciona o 9 para responder e para a memória por telefone ficar consistente.
function normBR(n) { n = String(n || ''); if (n.startsWith('55') && n.length === 12) return n.slice(0,4) + '9' + n.slice(4); return n; }

for (const item of $input.all()) {
  const body = item.json.body || {};
  const cfg = {
    phoneNumberId: item.json.phoneNumberId,
    restaurantNumber: item.json.restaurantNumber,
    graphVersion: item.json.graphVersion,
  };
  for (const entry of body.entry || []) {
    for (const change of entry.changes || []) {
      const v = change.value || {};
      const contacts = v.contacts || [];
      for (const m of v.messages || []) {
        if (m.type !== 'text') {
          out.push({ json: { ...cfg, from: normBR(m.from), fromRaw: m.from, name: contacts[0]?.profile?.name || '', text: '[mensagem não é texto]', unsupported: true, msgId: m.id } });
          continue;
        }
        out.push({ json: { ...cfg, from: normBR(m.from), fromRaw: m.from, name: contacts[0]?.profile?.name || '', text: m.text.body, unsupported: false, msgId: m.id } });
      }
    }
  }
}
return out;

// Separa a resposta visível do cliente dos blocos de controle [[PEDIDO]] e [[HUMANO]].
const src = $('Extrair mensagem').item.json;
let reply = ($json.output ?? $json.text ?? '').toString();

let order = null;
const m = reply.match(/\[\[PEDIDO\]\]([\s\S]*?)\[\[\/PEDIDO\]\]/);
if (m) {
  try { order = JSON.parse(m[1]); } catch (e) { order = { raw: m[1] }; }
  reply = reply.replace(m[0], '').trim();
}
const handoff = /\[\[HUMANO\]\]/.test(reply);
reply = reply.replace(/\[\[HUMANO\]\]/g, '').trim();

let staffMessage = null;
if (order) {
  const itens = (order.itens || []).map(i => `• ${i.qtd}x ${i.nome} — R$ ${Number(i.preco_unit || 0).toFixed(2)}`).join('\n');
  staffMessage = `🍔 NOVO PEDIDO (via Robin)\nCliente: ${order.nome || src.name} — wa.me/${src.from}\nModalidade: ${order.modalidade}\n${order.endereco ? 'Endereço: ' + order.endereco + '\n' : ''}Pagamento: ${order.pagamento}${order.troco_para ? ' (troco p/ ' + order.troco_para + ')' : ''}\n\n${itens}\n\nSubtotal: R$ ${Number(order.subtotal||0).toFixed(2)}\nEntrega: R$ ${Number(order.taxa_entrega||0).toFixed(2)}\nTOTAL: R$ ${Number(order.total||0).toFixed(2)}${order.observacoes ? '\nObs: ' + order.observacoes : ''}`;
} else if (handoff) {
  staffMessage = `🙋 CLIENTE PEDE ATENDENTE\n${src.name || ''} — wa.me/${src.from}\nÚltima mensagem: "${src.text}"`;
}

return [{ json: { ...src, reply, order, handoff, staffMessage } }];
